    private void SetPreviewContrast(DependencyObject root){if(root is BatteryRing ring){ring.PreviewLight=previewLight;ring.InvalidateVisual();}for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)SetPreviewContrast(VisualTreeHelper.GetChild(root,i));}
