    private void Slider(Panel p,string text,double v,double min,double max,double step,Action<double> set,bool play=false){
        var line=new Grid{Margin=new Thickness(0,4,0,4)};line.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(150)});line.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});line.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(72)});
        var label=Label(text);label.VerticalAlignment=VerticalAlignment.Center;line.Children.Add(label);
        var sl=new Slider{Minimum=min,Maximum=max,Value=Math.Clamp(v,min,max),TickFrequency=step,IsSnapToTickEnabled=true,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(8,0,10,0)};Grid.SetColumn(sl,1);line.Children.Add(sl);
        var num=new TextBox{Text=sl.Value.ToString("0.##",CultureInfo.InvariantCulture),VerticalAlignment=VerticalAlignment.Center,Padding=new Thickness(4),TextAlignment=TextAlignment.Right};Grid.SetColumn(num,2);line.Children.Add(num);p.Children.Add(line);
        void Demo(){if(play)Play(text.Contains("流光")?"charge":text.Contains("Fade In")?"in":text.Contains("Fade Out")||text.Contains("离线")||text.Contains("Off")?"out":text.Contains("圆环")||text.Contains("颜色")?"battery":"full");}
        sl.ValueChanged+=(_,_)=>{num.Text=sl.Value.ToString("0.##",CultureInfo.InvariantCulture);set(sl.Value);RingConfig.Notify();};
        void Commit(){if(double.TryParse(num.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out var n)&&double.IsFinite(n)){sl.Value=Math.Clamp(min+Math.Round((n-min)/step)*step,min,max);Demo();}num.Text=sl.Value.ToString("0.##",CultureInfo.InvariantCulture);}
        num.LostKeyboardFocus+=(_,_)=>Commit();num.KeyDown+=(_,e)=>{if(e.Key==System.Windows.Input.Key.Enter){Commit();e.Handled=true;}};if(play)sl.PreviewMouseLeftButtonUp+=(_,_)=>Demo();
    }
