    private void ColorEditor(Panel p,string name,string value,Action<string> set){var exp=new Expander{Header=name+" · "+value,Margin=new Thickness(0,3,0,3)};var box=new StackPanel{Margin=new Thickness(10,4,0,5)};exp.Content=box;p.Children.Add(exp);var c=RingPreferences.Ink(value);var swatch=new Border{Height=20,Background=new SolidColorBrush(c),CornerRadius=new CornerRadius(4)};box.Children.Add(swatch);var field=new TextBox{Text=value,Margin=new Thickness(0,5,0,5)};box.Children.Add(field);var sliders=new Slider[4];bool syncing=false;void Apply(Color color){swatch.Background=new SolidColorBrush(color);string hex=color.A==255?$"#{color.R:X2}{color.G:X2}{color.B:X2}":color.ToString();exp.Header=name+" · "+hex;set(hex);RingConfig.Notify();}field.TextChanged+=(_,_)=>{if(syncing)return;try{var x=ParseColor(field.Text);syncing=true;for(int i=0;i<4;i++)sliders[i].Value=new[]{x.R,x.G,x.B,x.A}[i];syncing=false;Apply(x);}catch{syncing=false;}};for(int i=0;i<4;i++){var line=new DockPanel();var l=Label(new[]{"R","G","B","A"}[i]);l.Width=20;line.Children.Add(l);var num=new TextBox{Text=new[]{c.R,c.G,c.B,c.A}[i].ToString(),Width=48,Margin=new Thickness(5,0,0,3)};DockPanel.SetDock(num,Dock.Right);line.Children.Add(num);var sl=new Slider{Minimum=0,Maximum=255,Value=new[]{c.R,c.G,c.B,c.A}[i],TickFrequency=1,IsSnapToTickEnabled=true};sliders[i]=sl;line.Children.Add(sl);box.Children.Add(line);num.LostKeyboardFocus+=(_,_)=>{if(int.TryParse(num.Text,out int n))sl.Value=Math.Clamp(n,0,255);num.Text=((int)sl.Value).ToString();};num.KeyDown+=(_,e)=>{if(e.Key==System.Windows.Input.Key.Enter){if(int.TryParse(num.Text,out int n))sl.Value=Math.Clamp(n,0,255);num.Text=((int)sl.Value).ToString();}};sl.ValueChanged+=(_,_)=>{num.Text=((int)sl.Value).ToString();if(syncing||sliders.Any(s=>s==null))return;var x=Color.FromArgb((byte)sliders[3].Value,(byte)sliders[0].Value,(byte)sliders[1].Value,(byte)sliders[2].Value);syncing=true;field.Text=x.ToString();syncing=false;Apply(x);};}}
    private void PaletteEditor(Panel parent,(string Name,string Value,Action<string> Set)[] entries){
        var card=new StackPanel();var grid=new WrapPanel{Margin=new Thickness(0,0,0,8)};card.Children.Add(grid);var editor=new StackPanel();card.Children.Add(editor);var swatches=new List<Border>();var codes=new List<TextBlock>();
        void Select(int i){editor.Children.Clear();var entry=entries[i];ColorEditor(editor,entry.Name,entry.Value,v=>{entries[i]=(entry.Name,v,entry.Set);entry.Set(v);swatches[i].Background=BrushFor(v);codes[i].Text=v;});if(editor.Children[0] is Expander e)e.IsExpanded=true;}
        for(int i=0;i<entries.Length;i++){int n=i;var entry=entries[i];var stack=new StackPanel();var swatch=new Border{Background=BrushFor(entry.Value),CornerRadius=new CornerRadius(5),Height=28,Margin=new Thickness(0,0,0,5),BorderBrush=BrushFor("#307F7F7F"),BorderThickness=new Thickness(1)};swatches.Add(swatch);stack.Children.Add(swatch);stack.Children.Add(new TextBlock{Text=entry.Name,TextWrapping=TextWrapping.Wrap});var code=new TextBlock{Text=entry.Value,FontSize=10,Opacity=.7};codes.Add(code);stack.Children.Add(code);var button=new Button{Content=stack,Width=110,HorizontalContentAlignment=HorizontalAlignment.Stretch,Padding=new Thickness(8),Margin=new Thickness(3)};button.Click+=(_,_)=>Select(n);grid.Children.Add(button);}
        parent.Children.Add(PanelCard(card,8));Select(0);
