    private FrameworkElement ThemePreview(RingPreferences theme){var strip=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};foreach(var (type,level) in new[]{(DeviceType.Mouse,85),(DeviceType.Headset,65),(DeviceType.Keyboard,15),(DeviceType.Gamepad,8)})strip.Children.Add(new BatteryRing{Width=45,Height=45,Margin=new Thickness(2),Preferences=theme,PreviewLight=false,DataContext=new TaskbarBattery(type,type.ToString(),level,"已连接",false,DateTimeOffset.MinValue,devices.FirstOrDefault(d=>d.Type==type)?.Key??("theme:"+type))});return new Border{Background=BrushFor("#20242C"),CornerRadius=new CornerRadius(7),Child=new Viewbox{Stretch=Stretch.Uniform,StretchDirection=StretchDirection.DownOnly,HorizontalAlignment=HorizontalAlignment.Center,Child=strip},Padding=new Thickness(8)};}
    private FrameworkElement ThemeCard(string name,RingPreferences theme,bool custom){var card=new StackPanel();card.Children.Add(ThemePreview(theme));card.Children.Add(new TextBlock{Text=name,FontSize=16,FontWeight=FontWeights.SemiBold,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,10,0,3)});var colors=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,3,0,7)};foreach(var hex in new[]{theme.Normal,theme.Low,theme.Critical,theme.Offline})colors.Children.Add(new Border{Background=BrushFor(hex),Width=17,Height=17,CornerRadius=new CornerRadius(5),Margin=new Thickness(0,0,5,0)});card.Children.Add(colors);var buttons=new WrapPanel();buttons.Children.Add(Btn("应用",()=>{RingThemes.Apply(theme);RingConfig.Notify();Build();}));if(custom){buttons.Children.Add(Btn("重命名",()=>RenameTheme(name,theme)));buttons.Children.Add(Btn("导出",()=>{var f=new SaveFileDialog{Filter="JSON|*.json",FileName="battery-theme.json"};if(f.ShowDialog()==true)System.IO.File.WriteAllText(f.FileName,System.Text.Json.JsonSerializer.Serialize(theme));}));buttons.Children.Add(Btn("删除",()=>{if(MessageBox.Show("删除主题 "+name+"？","主题",MessageBoxButton.YesNo)==MessageBoxResult.Yes){RingThemes.Delete(name);Build();}}));}card.Children.Add(buttons);var box=PanelCard(card,14);box.Margin=new Thickness(0);box.HorizontalAlignment=HorizontalAlignment.Stretch;return box;}
