    private static Color ParseColor(string value){var s=value.Trim();if(s.StartsWith("rgb",StringComparison.OrdinalIgnoreCase)||s.Contains(',')){s=s.Replace("rgba(","",StringComparison.OrdinalIgnoreCase).Replace("rgb(","",StringComparison.OrdinalIgnoreCase).TrimEnd(')');var a=s.Split(',').Select(x=>double.Parse(x.Trim(),CultureInfo.InvariantCulture)).ToArray();if(a.Length is not (3 or 4)||a.Take(3).Any(x=>x<0||x>255)||a.Length==4&&(a[3]<0||a[3]>1))throw new FormatException();return Color.FromArgb(a.Length==4?(byte)Math.Round(a[3]*255):(byte)255,(byte)a[0],(byte)a[1],(byte)a[2]);}return (Color)ColorConverter.ConvertFromString(s);}
