    private void AppearanceThemeSelector(Panel p){var row=new DockPanel{Margin=new Thickness(0,0,0,8)};var lab=Label("主题  ");DockPanel.SetDock(lab,Dock.Left);row.Children.Add(lab);var built=PresetThemes();var names=built.Select(t=>t.Name).Concat(RingThemes.All.Keys).Prepend("当前自定义设置").ToArray();var selector=new ComboBox{ItemsSource=names,SelectedIndex=0};row.Children.Add(selector);selector.SelectionChanged+=(_,_)=>{int i=selector.SelectedIndex;if(i<=0)return;if(i<=built.Length)RingThemes.Apply(built[i-1].Settings);else if(RingThemes.All.TryGetValue(names[i],out var t))RingThemes.Apply(t);RingConfig.Notify();Build();};p.Children.Add(row);}
    private static (string Name,RingPreferences Settings)[] PresetThemes()=>new[]{("Apple Classic",new RingPreferences()),("Ocean Blue",new RingPreferences{Normal="#0A84FF",Low="#64D2FF",Critical="#BF5AF2"}),("Pastel Pink",new RingPreferences{Normal="#F5A9CF",Low="#C8B6FF",Critical="#FF7799"}),("Minimal White",new RingPreferences{Normal="#FFFFFF",Low="#BBBBBB",Critical="#888888"})};
