            TextEntry(panel,"自定义名称",c.Names.GetValueOrDefault(d.Key,d.Name),v=>c.Names[d.Key]=v);if(d.Offline)panel.Children.Add(Btn("移除记录",()=>forget(d.Key)));
            var group=groups.FirstOrDefault(g=>g.Reading.Key==d.Key);if(group!=null){var sources=new StackPanel{Margin=new Thickness(4,4,4,4)};sources.Children.Add(Label(string.Join(" · ",group.Sources.Select(x=>DeviceIdentityManager.Source(x.Key)).Distinct())));if(group.Inferred)sources.Children.Add(Label("自动匹配：唯一 Logitech 型号（非序列号确认）；若为两台设备，可解除合并。"));foreach(var source in group.Sources)sources.Children.Add(Label($"{DeviceIdentityManager.Source(source.Key)} · {source.Name}"));var options=group.Sources.Select(x=>x.Key).Prepend("").ToArray();var selector=new ComboBox{ItemsSource=options.Select(k=>k==""?"自动选择":DeviceIdentityManager.Source(k)+" · "+k).ToArray(),SelectedIndex=Math.Max(0,Array.IndexOf(options,c.PreferredSources.GetValueOrDefault(d.Key,"")))};sources.Children.Add(Label("首选数据来源（离线时自动回退）"));sources.Children.Add(selector);selector.SelectionChanged+=(_,_)=>{if(selector.SelectedIndex<0)return;var key=options[selector.SelectedIndex];if(key=="")c.PreferredSources.Remove(d.Key);else c.PreferredSources[d.Key]=key;RingConfig.Notify();};if(group.Sources.Length>1)sources.Children.Add(Btn("解除合并",()=>{DeviceIdentityManager.Split(c,group);RingConfig.Notify();Build();}));sources.Children.Add(Btn("忽略设备",()=>{if(!c.IgnoredDevices.Contains(d.Key))c.IgnoredDevices.Add(d.Key);RingConfig.Notify();Build();}));panel.Children.Add(new Expander{Header="数据来源 · "+group.Sources.Length,Content=sources});}

